script:
// Script de criação (MongoDB) gerado pelo ModelForge a partir do modelo "Loja".
// Os tipos vêm do que foi modelado - confira antes de rodar contra um banco real.

db.createCollection("usuarios", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      properties: {
        "nome": { bsonType: "string" },
        "idade": { bsonType: "number" },
        "ativo": { bsonType: "bool" },
        "criado": { bsonType: "date" },
        "tags": { bsonType: "array" },
        "dono": { bsonType: "objectId" },
        "endereco": {
          bsonType: "object",
          properties: {
            "rua": { bsonType: "string" },
            "geo": {
              bsonType: "object",
              properties: {
                "lat": { bsonType: "number" },
                "lng": { bsonType: "number" }
              }
            }
          }
        },
        "itens": {
          bsonType: "array",
          items: {
            bsonType: "object",
            properties: {
              "sku": { bsonType: "string" },
              "qtd": { bsonType: "number" }
            }
          }
        }
      }
    }
  }
});

db.createCollection("pedidos", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      properties: {
        "usuario": { bsonType: "objectId" },  // referência -> usuarios
        "total": { bsonType: "number" },
        "linhas": {
          bsonType: "array",
          items: {
            bsonType: "object",
            properties: {
              "produto": { bsonType: "objectId" },  // referência -> produtos
              "qtd": { bsonType: "number" }
            }
          }
        }
      }
    }
  }
});
db.pedidos.createIndex({ "usuario": 1 }); // referência -> usuarios
